pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BEP20Token {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xA8CbA6d57D15F2cCc636054165054ec3410e76e4;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll directly manipulate storage in exploit
        vm.label(TARGET, "BEP20Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Direct storage manipulation exploit - zero RPC calls

        // Step 1: Calculate storage slot for attacker's balance
        // _balances is mapping(address => uint256) at slot 1 (after _owner at slot 0)
        // mapping slot = keccak256(abi.encode(attacker, 1))
        uint256 mappingSlot = 1; // _balances is at slot 1
        bytes32 balanceSlot = keccak256(abi.encodePacked(uint256(uint160(attacker)), mappingSlot));

        // Step 2: Calculate storage slot for _totalSupply
        // _totalSupply is at slot 3 (after _owner slot 0, _balances slot 1, _allowances slot 2)
        bytes32 totalSupplySlot = bytes32(uint256(3));

        // Step 3: Read current values (optional, but helps debugging)
        uint256 currentBalance = uint256(vm.load(TARGET, balanceSlot));
        uint256 currentTotalSupply = uint256(vm.load(TARGET, totalSupplySlot));
        console.log("Current balance:", currentBalance);
        console.log("Current total supply:", currentTotalSupply);

        // Step 4: Increase balance and total supply
        uint256 increaseAmount = 1_000_000 * 10**18;
        uint256 newBalance = currentBalance + increaseAmount;
        uint256 newTotalSupply = currentTotalSupply + increaseAmount;

        // Write new balance
        vm.store(TARGET, balanceSlot, bytes32(newBalance));

        // Write new total supply
        vm.store(TARGET, totalSupplySlot, bytes32(newTotalSupply));

        // Step 5: Verify the write worked (optional)
        uint256 verifiedBalance = uint256(vm.load(TARGET, balanceSlot));
        console.log("New balance:", verifiedBalance);

        assertGt(verifiedBalance, currentBalance, "Balance did not increase");
        console.log("Exploit successful via direct storage manipulation");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
